import React, { useState, useEffect } from 'react';
import { getFranchises, updateExamData, deleteExamData } from '../services/api';
import { Router } from 'react-router-dom';

const ExamData = () => {
  const [filterFranchiseId, setFilterFranchiseId] = useState('');
  const [franchises, setFranchises] = useState([]);
  const [examDataList, setExamDataList] = useState([]);
  const [editingExam, setEditingExam] = useState(null); 
  
  

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []);

  

  const getFranchiseExams = (franchiseId) => {
    const franchise = franchises.find((f) => f._id === franchiseId);
    return franchise ? franchise.examData : [];
  };

 
  const handleFilterChange = (e) => {
    const selectedFranchiseId = e.target.value;
    setFilterFranchiseId(selectedFranchiseId);
    if (selectedFranchiseId) {
      const exams = getFranchiseExams(selectedFranchiseId);
      setExamDataList(exams);
    } else {
      setExamDataList([]);
    }
  };



  const handleDeleteExam = async (examId) => {
    try {
   
      await deleteExamData(filterFranchiseId, examId); 
     
      setExamDataList(examDataList.filter((exam) => exam._id !== examId));
      alert('Exam deleted successfully');
    } catch (error) {
      console.error('Error deleting exam:', error);
      alert('Failed to delete exam');
    }
  };

  

  // Handle edit exam (open the edit form)
  const handleEditExam = (exam) => {
    const franchiseId = filterFranchiseId;
    const updatedExam = { ...exam, franchiseId };
    console.log('Editing Exam with franchiseId:', updatedExam);
    setEditingExam(updatedExam);
  };



  // Handle form input changes for editing
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setEditingExam((prevExam) => ({
      ...prevExam,
      [name]: value,
    }));
  };

  // Handle save exam (update the exam data)
  const handleSaveExam = async (e) => {
    e.preventDefault();

    console.log('Saving Exam:', editingExam);
    if (!editingExam.franchiseId || !editingExam._id) {
      console.error('Missing franchiseId or _id in editingExam:', editingExam);
      return;
    }

    try {
      const updatedExam = await updateExamData(editingExam);
      setExamDataList((prevData) =>
        prevData.map((exam) =>
          exam._id === updatedExam._id ? updatedExam : exam
        )
      );
      setEditingExam(null); // Close the edit form
      alert('Exam updated successfully');
      window.location.reload()
    } catch (error) {
      console.error('Error saving exam data:', error);
      alert('Failed to update exam');
    }
  };

  

  return (
    <div>
      <h1>Manage Exam Data</h1>

      {/* Franchise filter dropdown */}
      <div>
        <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
        <select
          id="filterFranchiseId"
          name="filterFranchiseId"
          value={filterFranchiseId}
          onChange={handleFilterChange}
        >
          <option value="">All</option>
          {franchises.map((franchise) => (
            <option key={franchise._id} value={franchise._id}>
              {franchise.name}
            </option>
          ))}
        </select>
      </div>

      {/* Render edit form if editing an exam */}
      {editingExam ? (
        <div>
          <h2>Edit Exam</h2>
          <form onSubmit={handleSaveExam}>
            <div>
              <label>Exam Name:</label>
              <input
                type="text"
                name="examName"
                value={editingExam.examName}
                onChange={handleInputChange}
              />
            </div>
            <div>
              <label>Date:</label>
              <input
                type="date"
                name="date"
                value={editingExam.date}
                onChange={handleInputChange}
              />
            </div>
            <div>
              <label>Students Attended:</label>
              <input
                type="number"
                name="studentsAttended"
                value={editingExam.studentsAttended}
                onChange={handleInputChange}
              />
            </div>
            <button type="submit">Save Changes</button>
            <button type="button" onClick={() => setEditingExam(null)}>
              Cancel
            </button>
          </form>
        </div>
      ) : (
        <h2>Exam Data</h2>
      )}

      {/* Table to display exam data */}
      {examDataList.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {examDataList.map((exam, index) => (
              <tr key={index}>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
                <td>
                  <button onClick={() => handleEditExam(exam)}>Edit</button>
                  <button onClick={() => handleDeleteExam(exam._id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for the selected franchise.</p>
      )}
    </div>
  );
};

export default ExamData;
